using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Interop;using System.Runtime.InteropServices;using System.Windows.Automation;using Gunt.ControlCenter.Services;using Gunt.ControlCenter.Models;
namespace Gunt.ControlCenter.Views {
 public sealed class DeveloperPopup:Window {
  readonly DesktopService service;readonly string root;readonly Action<string> navigate;readonly TextBlock feedback=new TextBlock{TextWrapping=TextWrapping.Wrap};readonly StackPanel panel=new StackPanel{Margin=new Thickness(16)};readonly Brush surface=(Brush)new BrushConverter().ConvertFromString("#0E0E12"),text=(Brush)new BrushConverter().ConvertFromString("#F4F4F5"),muted=(Brush)new BrushConverter().ConvertFromString("#A1A1AA");bool busy,ready;
  public DeveloperPopup(string directory,bool palette,Action<string> navigate=null){root=directory;service=new DesktopService(root);this.navigate=navigate;Title=palette?"GUnT_0x9 명령 팔레트":"GUnT_0x9 빠른 패널";Width=palette?560:420;Height=palette?430:Double.NaN;SizeToContent=palette?SizeToContent.Manual:SizeToContent.Height;MaxHeight=650;MinWidth=350;MinHeight=palette?350:0;Background=surface;Foreground=text;FontFamily=new FontFamily("S-Core Dream 5 Medium, Segoe UI Variable");FontSize=14;ShowInTaskbar=false;Topmost=true;WindowStartupLocation=WindowStartupLocation.CenterScreen;var button=new Style(typeof(Button));button.Setters.Add(new Setter(Control.BackgroundProperty,new SolidColorBrush(Color.FromRgb(21,21,28))));button.Setters.Add(new Setter(Control.ForegroundProperty,text));button.Setters.Add(new Setter(Control.BorderBrushProperty,new SolidColorBrush(Color.FromRgb(35,35,43))));button.Setters.Add(new Setter(Control.PaddingProperty,new Thickness(10,7,10,7)));button.Setters.Add(new Setter(FrameworkElement.MarginProperty,new Thickness(0,0,6,6)));button.Setters.Add(new Setter(Control.TemplateProperty,(ControlTemplate)System.Windows.Markup.XamlReader.Parse(@"<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' TargetType='Button'><Border Name='B' Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='1' CornerRadius='3' Padding='{TemplateBinding Padding}'><ContentPresenter TextElement.Foreground='{TemplateBinding Foreground}' HorizontalAlignment='Center'/></Border><ControlTemplate.Triggers><Trigger Property='IsMouseOver' Value='True'><Setter TargetName='B' Property='Background' Value='#1B1B24'/></Trigger><Trigger Property='IsKeyboardFocused' Value='True'><Setter TargetName='B' Property='BorderBrush' Value='#A78BFA'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter TargetName='B' Property='Opacity' Value='0.4'/></Trigger></ControlTemplate.Triggers></ControlTemplate>")));Resources.Add(typeof(Button),button);var input=new Style(typeof(TextBox));input.Setters.Add(new Setter(Control.BackgroundProperty,new SolidColorBrush(Color.FromRgb(21,21,28))));input.Setters.Add(new Setter(Control.ForegroundProperty,text));input.Setters.Add(new Setter(Control.PaddingProperty,new Thickness(8)));Resources.Add(typeof(TextBox),input);var inputList=new Style(typeof(ListBox));inputList.Setters.Add(new Setter(Control.BackgroundProperty,new SolidColorBrush(Color.FromRgb(21,21,28))));inputList.Setters.Add(new Setter(Control.ForegroundProperty,text));Resources.Add(typeof(ListBox),inputList);Content=new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};if(palette)BuildPalette();else BuildPanel();feedback.Foreground=muted;panel.Children.Add(feedback);PreviewKeyDown+=delegate(object s,KeyEventArgs e){if(e.Key==Key.Escape&&!busy){Close();e.Handled=true;}};SourceInitialized+=delegate{int dark=1;DwmSetWindowAttribute(new WindowInteropHelper(this).Handle,20,ref dark,4);};Loaded+=delegate{Position(palette);ready=true;};Closing+=delegate(object sender,System.ComponentModel.CancelEventArgs e){if(busy){e.Cancel=true;feedback.Text="실행 요청 처리 중입니다. 완료 후 닫으세요.";}};Deactivated+=delegate{if(!palette&&ready&&!busy&&!IsOwnedDialogOpen())Close();};}
  bool IsOwnedDialogOpen(){return OwnedWindows.Count>0;}
  void Position(bool palette){var point=System.Windows.Forms.Cursor.Position;var screen=System.Windows.Forms.Screen.FromPoint(point);var work=screen.WorkingArea;double scale=GuntLayout.Scale(screen);var h=new WindowInteropHelper(this).Handle;int width=(int)Math.Min(Width*scale,work.Width-16),height=(int)Math.Min(ActualHeight*scale,work.Height-16);int x=palette?work.Left+(work.Width-width)/2:Math.Max(work.Left+8,Math.Min(point.X,work.Right-width-8));int y=palette?work.Top+(work.Height-height)/3:work.Top+8;SetWindowPos(h,IntPtr.Zero,x,y,width,height,0x14);}
  [DllImport("dwmapi.dll")]static extern int DwmSetWindowAttribute(IntPtr h,int attribute,ref int value,int size);
  [DllImport("user32.dll")]static extern bool SetWindowPos(IntPtr h,IntPtr a,int x,int y,int w,int z,uint flags);
  void Label(string value,bool secondary=false){panel.Children.Add(new TextBlock{Text=value,Foreground=secondary?muted:text,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,10)});}
  Button Button(Panel p,string title,Action action){var b=new Button{Content=title};AutomationProperties.SetName(b,title);b.Click+=delegate{try{action();}catch(Exception e){feedback.Text="처리 실패: "+e.Message;}};p.Children.Add(b);return b;}
  void Page(string id){if(navigate!=null)navigate(id);else service.OpenControlCenter(id);Close();}
  IEnumerable<Button> PopupButtons(DependencyObject parent){for(int i=0;i<VisualTreeHelper.GetChildrenCount(parent);i++){var child=VisualTreeHelper.GetChild(parent,i);var button=child as Button;if(button!=null)yield return button;foreach(var nested in PopupButtons(child))yield return nested;}}
  void Run(Func<string> action){if(busy)return;busy=true;var buttons=PopupButtons(panel).Where(b=>b.IsEnabled).ToArray();foreach(var button in buttons)button.IsEnabled=false;feedback.Text="처리 중…";Task.Factory.StartNew(action).ContinueWith(t=>Dispatcher.BeginInvoke((Action)delegate{busy=false;foreach(var button in buttons)button.IsEnabled=true;feedback.Text=t.IsFaulted?"실행 실패: "+t.Exception.GetBaseException().Message:t.Result;}));}
  void BuildPanel(){Label("빠른 개발 작업");ProjectEntry project=null;try{project=service.ActiveProject();Label(project.Name);Label(project.Directory,true);}catch(Exception e){Label(e.Message,true);}var actions=new WrapPanel();panel.Children.Add(actions);Button(actions,"프로젝트 선택",()=>Page("developer-setup"));foreach(var tool in new[]{new[]{"Codex","codex"},new[]{"OpenCode","opencode"},new[]{"VS Code","ide"},new[]{"폴더","folder"}}){string kind=tool[1];var launch=Button(actions,tool[0],()=>Run(()=>{var current=service.ActiveProject();if(project==null||current.Id!=project.Id||current.Directory!=project.Directory)throw new InvalidOperationException("선택 프로젝트가 변경됐습니다. 빠른 패널을 다시 열어 확인하세요.");return service.LaunchDeveloper(current,kind);}));launch.IsEnabled=project!=null;if(project==null){launch.ToolTip="프로젝트를 먼저 선택하세요.";ToolTipService.SetShowOnDisabled(launch,true);}}Button(actions,"개발 세션 시작",StartSessionQuick);Label("작업공간: "+service.ProfileState(),true);var desktop=new WrapPanel();panel.Children.Add(desktop);Button(desktop,"모니터 표시 / 숨김",()=>Run(()=>{service.Action("monitor-toggle");return "실제 모니터 전환 요청을 전달했습니다.";}));Button(desktop,"배경 재생 / 정지",()=>Run(()=>{service.Action("wallpaper-toggle");return "기존 배경의 수동 재생 정책 전환 요청을 전달했습니다.";}));Button(desktop,"프로필",()=>Page("profiles"));Button(desktop,"제어 센터",()=>Page("overview"));Button(desktop,"명령 팔레트",()=>{service.OpenControlCenter("palette");Close();});}
  void StartSessionQuick(){try{var p=service.ActiveProject();var prefs=service.Preferences(p);var preset=service.Sessions().Presets.FirstOrDefault(x=>x.Id==prefs.SessionPreset);if(preset==null)throw new ArgumentException("기본 개발 세션을 개발 설정에서 선택하세요.");busy=true;bool yes;try{yes=MessageBox.Show(this,service.SessionPreview(p,preset),"개발 세션 시작",MessageBoxButton.OKCancel,MessageBoxImage.Question,MessageBoxResult.Cancel)==MessageBoxResult.OK;}finally{busy=false;}if(!yes)return;bool command=false;if(preset.Actions.Any(x=>x.Enabled&&x.Kind=="command")){busy=true;try{command=MessageBox.Show(this,String.Join("\n",p.Commands??new List<string>()),"프로젝트 명령 실행 허용",MessageBoxButton.YesNo,MessageBoxImage.Question,MessageBoxResult.No)==MessageBoxResult.Yes;}finally{busy=false;}}Run(()=>{var run=service.StartSession(p,preset,command);return run.Result+"\n"+String.Join("\n",run.Actions.Select(x=>x.ToString()));});}catch(Exception e){feedback.Text=e.Message;}}
  void BuildPalette(){Label("GUNT 명령 찾기");var query=new TextBox{Margin=new Thickness(0,0,0,10)};AutomationProperties.SetName(query,"GUNT 명령 검색");panel.Children.Add(query);var list=new ListBox{Height=240};AutomationProperties.SetName(list,"GUNT 명령 결과");panel.Children.Add(list);Action filter=()=>{try{list.ItemsSource=service.SearchCommands(query.Text);if(list.Items.Count>0)list.SelectedIndex=0;}catch(Exception e){feedback.Text=e.Message;}};query.TextChanged+=delegate{filter();};Action execute=()=>{try{if(busy){feedback.Text="현재 실행 요청을 처리 중입니다.";return;}var command=list.SelectedItem as CommandEntry;if(command==null)return;if(command.Action=="page"){service.RememberCommand(command.Id);Page(command.Value);}else if(command.Action=="session"){StartSessionQuick();}else if(command.Action=="panel"){service.OpenControlCenter("quick-panel");Close();}else Run(()=>service.ExecuteCommand(command));}catch(Exception e){feedback.Text=e.Message;}};PreviewKeyDown+=delegate(object sender,KeyEventArgs e){if(e.Key==Key.Down||e.Key==Key.Up){if(list.Items.Count>0){list.SelectedIndex=Math.Max(0,Math.Min(list.Items.Count-1,list.SelectedIndex+(e.Key==Key.Down?1:-1)));list.ScrollIntoView(list.SelectedItem);}e.Handled=true;}else if(e.Key==Key.Enter){execute();e.Handled=true;}};list.MouseDoubleClick+=delegate{execute();};var a=new WrapPanel();panel.Children.Add(a);Button(a,"선택 명령 실행",execute);Button(a,"즐겨찾기 전환",()=>{var c=list.SelectedItem as CommandEntry;if(c==null)return;service.FavoriteCommand(c.Id);filter();});filter();Loaded+=delegate{query.Focus();};}
 }
}
